use base64::{Engine, prelude::BASE64_STANDARD};

/// Base64-encoded DER of the Google Key Attestation ECDSA root CA.
const TRUST_ANCHOR_EC_DER_B64: &str = "";

/// Base64-encoded DER of the Google Key Attestation RSA root CA.
const TRUST_ANCHOR_RSA_DER_B64: &str = "";

/// Base64-encoded DER of the Google Key Attestation EC root CA for emulators.
const _TRUST_ANCHOR_EMULATOR: &str = "";

/// Returns DER-encoded bytes for the built-in trust anchors
/// (Google Key Attestation EC and RSA root CAs).
pub fn default_trust_anchor_ders() -> Vec<Vec<u8>> {
    [
        ("TRUST_ANCHOR_EC_DER_B64",  TRUST_ANCHOR_EC_DER_B64),
        ("TRUST_ANCHOR_RSA_DER_B64", TRUST_ANCHOR_RSA_DER_B64),
    ]
    .iter()
    .map(|(name, b64)| {
        BASE64_STANDARD
            .decode(b64)
            .unwrap_or_else(|_| panic!("{name} constant is not valid base64"))
    })
    .collect()
}
